package com.nth.desktop3d.test;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import com.nth.desktop3d.*;
import java.lang.reflect.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BooleanSupplier;

/** Pixel-level fade/alignment and real card/document/remote-overlay behavior. */
final class PolishSmoke {
    private final Instrumentation test;private final MainActivity activity;private final String output;
    PolishSmoke(Instrumentation test,MainActivity activity,String output){this.test=test;this.activity=activity;this.output=output;}
    void run()throws Exception{
        main(()->{fadePixels();iconAlignment();});
        invoke("showSettings",new Class[]{String.class},"look");
        check(findText("Opacity over content  ·  90")!=null&&findText("Fade width  ·  80")!=null,"Fresh install glass defaults are not 90/80");
        SharedPreferences prefs=test.getTargetContext().getSharedPreferences("desktop3d",0);
        main(()->prefs.edit().putBoolean("card_photos",true).apply());
        main(()->prefs.edit().putInt("glass_strength",70).putInt("glass_feather",40).putBoolean("adaptive_glass",false).apply());invoke("showSettings",new Class[]{String.class},"look");
        check(findText("Opacity over content  ·  70")!=null&&findText("Fade width  ·  40")!=null,"User glass preferences were overwritten");
        main(()->prefs.edit().putInt("glass_strength",90).putInt("glass_feather",80).putBoolean("adaptive_glass",true).apply());invoke("showSettings",new Class[]{String.class},"root");
        View list=find(activity.getWindow().getDecorView(),v->v.getClass().getSimpleName().equals("FadingSettingsScrollView"));main(()->((ScrollView)list).scrollTo(0,280));idle(300);capture("settings-fade-boundary");
        invoke("showCards",new Class[]{String.class},"");await(()->findText("Media controls")!=null,"Crystal cards did not open");check(findText("Choose weather city")!=null,"Weather card action missing");capture("crystal-cards");
        invoke("showSettings",new Class[]{String.class},"cards");Switch notes=(Switch)find(activity.getWindow().getDecorView(),v->v instanceof Switch&&"Notes".contentEquals(((Switch)v).getText()));check(notes!=null,"Card visibility control missing");main(notes::performClick);check(!prefs.getBoolean("card_notes",true),"Card visibility did not persist");invoke("showCards",new Class[]{String.class},"");check(findText("Notes")==null,"Disabled card is still shown");main(()->prefs.edit().putBoolean("card_notes",true).apply());
        invoke("showCards",new Class[]{String.class},"reading");tapText("Add reading link");setNodeText("Title","Smoke reading link");setNodeText("https://…","https://example.org/reading-smoke");clickSystem("Save");await(()->findText("Smoke reading link")!=null,"Saved reading card was not rendered");check(prefs.getString("card_bookmarks","").contains("reading-smoke"),"Reading link was not persisted");capture("crystal-reading-card");
        java.io.File imageFile=new java.io.File(test.getTargetContext().getExternalFilesDir(null),"card-smoke.png");Bitmap photo=Bitmap.createBitmap(48,48,Bitmap.Config.ARGB_8888);photo.eraseColor(0xFF58B9DB);try(java.io.FileOutputStream stream=new java.io.FileOutputStream(imageFile)){photo.compress(Bitmap.CompressFormat.PNG,100,stream);}photo.recycle();
        IntentFilter filter=new IntentFilter(Intent.ACTION_OPEN_DOCUMENT);filter.addCategory(Intent.CATEGORY_OPENABLE);filter.addDataType("image/*");Instrumentation.ActivityMonitor monitor=test.addMonitor(filter,new Instrumentation.ActivityResult(Activity.RESULT_OK,new Intent().setData(Uri.fromFile(imageFile))),true);
        invoke("showCards",new Class[]{String.class},"photos");tapText("Choose photos");idle(500);test.removeMonitor(monitor);await(()->find(activity.getWindow().getDecorView(),v->v instanceof ImageView&&v.getContentDescription()!=null&&v.getContentDescription().toString().startsWith("Saved photo")&&((ImageView)v).getDrawable()!=null)!=null,"Selected photo was not decoded into the crystal card");check(prefs.getBoolean("card_photos",true)&&prefs.getString("card_photo_uris","").contains("card-smoke"),"Photo content replaced the card visibility setting");capture("crystal-photo-card");
        main(()->{prefs.edit().remove("card_photo_uris").remove("card_bookmarks").apply();activity.onBackPressed();});
        CrystalPreferences crystal=new CrystalPreferences(activity);int original=crystal.feedProvider();boolean enabled=crystal.feedEnabled(),edge=crystal.feedEdgeSwipe();
        main(()->{crystal.setFeedEnabled(false);});check(Boolean.FALSE.equals(invoke("feed",new Class[0])),"Disabled feed still opened");
        main(()->{crystal.setFeedEnabled(true);crystal.setFeedEdgeSwipe(true);crystal.setFeedProvider(2);});check(Boolean.TRUE.equals(invoke("feed",new Class[0])),"Nth Feed did not handle the boundary swipe");await(()->field(activity,"nativeFeed")!=null,"Nth Feed did not show native news");
        main(()->{activity.onBackPressed();crystal.setFeedProvider(0);Object client=field(activity,"discover");set(client,"targetOverride","com.nth.desktop3d.widgetfixture");call(client,"reconnect");call(client,"resume");});
        invoke("feed",new Class[0]);await(()->systemHas("Discover protocol fixture"),"Remote Discover overlay did not render from the separate UID");capture("discover-cross-process-overlay");
        check(((View)field(activity,"root")).getTranslationX()>0,"Overlay scroll callback did not move the desktop");clickSystem("Close fixture feed");await(()->((View)field(activity,"root")).getTranslationX()==0,"Closing Discover did not restore the desktop");
        invoke("feed",new Class[0]);await(()->systemHas("Discover protocol fixture"),"Overlay could not reopen");main(()->call(field(activity,"discover"),"pause"));await(()->((View)field(activity,"root")).getTranslationX()==0,"Pausing did not restore the desktop");
        main(()->{Object client=field(activity,"discover");call(client,"resume");set(client,"targetOverride",null);call(client,"reconnect");});invoke("feed",new Class[0]);await(()->findText("Reconnect Google Discover")!=null,"Missing Google app did not expose a usable setup fallback");capture("discover-direct-fallback");
        main(()->{activity.onBackPressed();crystal.setFeedProvider(original);crystal.setFeedEnabled(enabled);crystal.setFeedEdgeSwipe(edge);call(field(activity,"discover"),"disable");});
    }
    private void fadePixels(){try{
        Context context=test.getTargetContext();Class<?> type=Class.forName("com.nth.desktop3d.FadingSettingsScrollView");Constructor<?> constructor=type.getDeclaredConstructor(Context.class);constructor.setAccessible(true);ScrollView scroll=(ScrollView)constructor.newInstance(context);FrameLayout root=new FrameLayout(context);View preview=new View(context);preview.setBackgroundColor(Color.GREEN);root.addView(preview,new FrameLayout.LayoutParams(160,40));View content=new View(context);content.setBackgroundColor(Color.MAGENTA);content.setMinimumHeight(400);scroll.addView(content,new ScrollView.LayoutParams(160,400));FrameLayout.LayoutParams params=new FrameLayout.LayoutParams(160,100);params.topMargin=40;root.addView(scroll,params);root.measure(View.MeasureSpec.makeMeasureSpec(160,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(160,View.MeasureSpec.EXACTLY));root.layout(0,0,160,160);scroll.scrollTo(0,80);check(scroll.getScrollY()==80,"Fade fixture must actually scroll before testing the edge");Bitmap pixels=Bitmap.createBitmap(160,160,Bitmap.Config.ARGB_8888);root.draw(new Canvas(pixels));check(pixels.getPixel(80,20)==Color.GREEN,"Settings scroll painted over the preview");check(Color.alpha(pixels.getPixel(80,42))<70&&Color.alpha(pixels.getPixel(80,100))>240,"Settings text edge did not fade to transparency: top="+Color.alpha(pixels.getPixel(80,42))+", center="+Color.alpha(pixels.getPixel(80,100)));pixels.recycle();
    }catch(ReflectiveOperationException failure){throw new AssertionError(failure);}}
    private void iconAlignment(){try{Class<?> type=Class.forName("com.nth.desktop3d.IconTile");Constructor<?> constructor=type.getDeclaredConstructor(Context.class,String.class,android.graphics.drawable.Drawable.class,String.class);constructor.setAccessible(true);ViewGroup first=(ViewGroup)constructor.newInstance(activity,"Short",null,"builtin:notes"),longName=(ViewGroup)constructor.newInstance(activity,"5e Companion App",null,"builtin:notes");for(View view:new View[]{first,longName}){view.measure(View.MeasureSpec.makeMeasureSpec(110,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(150,View.MeasureSpec.EXACTLY));view.layout(0,0,110,150);}check(first.getChildAt(0).getTop()==longName.getChildAt(0).getTop()&&first.getChildAt(0).getLeft()==longName.getChildAt(0).getLeft(),"Long labels displaced the icon");TextView label=(TextView)longName.getChildAt(1);check("5e Compa...".contentEquals(label.getText())&&label.getMaxLines()==1,"Long icon labels are not one-line eight-character ellipses");check("5e Companion App".contentEquals(longName.getContentDescription()),"Full app name was lost to accessibility");}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}}
    private interface Match{boolean test(View view);}
    private View find(View view,Match match){if(view.getVisibility()!=View.VISIBLE)return null;if(match.test(view))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=find(((ViewGroup)view).getChildAt(i),match);if(found!=null)return found;}return null;}
    private View findText(String text){return find(activity.getWindow().getDecorView(),v->v instanceof TextView&&text.contentEquals(((TextView)v).getText()));}
    private void tapText(String text){await(()->{View view=findText(text);return view!=null&&view.isAttachedToWindow()&&view.getWidth()>0&&view.getHeight()>0;},"Card action missing or not laid out: "+text);AtomicReference<View> ref=new AtomicReference<>();main(()->ref.set(findText(text)));View view=ref.get();main(()->view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),true));idle(300);int[] position=new int[2];main(()->view.getLocationOnScreen(position));long time=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(time,SystemClock.uptimeMillis(),action,position[0]+view.getWidth()/2f,position[1]+view.getHeight()/2f,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(test.getUiAutomation().injectInputEvent(event,true),"Card native tap failed");event.recycle();}idle(300);}
    private AccessibilityNodeInfo node(AccessibilityNodeInfo root,String value,boolean hint){if(root==null)return null;CharSequence text=hint?root.getHintText():root.getText();if(text!=null&&value.equalsIgnoreCase(text.toString().trim()))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo found=node(root.getChild(i),value,hint);if(found!=null)return found;}return null;}
    private void setNodeText(String hint,String value){long end=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo found=node(test.getUiAutomation().getRootInActiveWindow(),hint,true);if(found!=null){Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);check(found.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args),"Dialog input failed: "+hint);return;}idle(150);}throw new AssertionError("Dialog field missing: "+hint);}
    private boolean systemHas(String text){return node(test.getUiAutomation().getRootInActiveWindow(),text,false)!=null;}
    private void clickSystem(String text){long end=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo found=node(test.getUiAutomation().getRootInActiveWindow(),text,false);while(found!=null){if(found.isClickable()&&found.performAction(AccessibilityNodeInfo.ACTION_CLICK)){idle(300);return;}found=found.getParent();}idle(150);}throw new AssertionError("System action missing: "+text);}
    private Object invoke(String name,Class<?>[] types,Object...args){AtomicReference<Object> value=new AtomicReference<>();main(()->{try{Method method=MainActivity.class.getDeclaredMethod(name,types);method.setAccessible(true);value.set(method.invoke(activity,args));}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}});idle(300);return value.get();}
    private Object field(Object target,String name){try{Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(target);}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}}
    private void set(Object target,String name,Object value){try{Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);field.set(target,value);}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}}
    private void call(Object target,String name){try{Method method=target.getClass().getDeclaredMethod(name);method.setAccessible(true);method.invoke(target);}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}}
    private void main(Runnable work){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{work.run();}catch(Throwable failure){error.set(failure);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void await(BooleanSupplier condition,String message){long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){if(condition.getAsBoolean())return;idle(100);}throw new AssertionError(message);}
    private void idle(long delay){SystemClock.sleep(delay);test.runOnMainSync(()->{});}
    private void capture(String name){idle(500);Bitmap bitmap=test.getUiAutomation().takeScreenshot();check(bitmap!=null,"Screenshot failed");java.io.File directory=output==null?new java.io.File(test.getTargetContext().getExternalFilesDir(null),"verification"):new java.io.File(output);directory.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(directory,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}catch(java.io.IOException failure){throw new AssertionError(failure);}finally{bitmap.recycle();}}
    private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
}
